			\label{eq:qld-4-12-cons-m-hat2}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\alice \alice'} \approx_{\delta_Q}  \Big ( \sum_{\substack{a,b: \\ \alpha a + \beta b = c}} \hat{M}^{(\Point,Z),z}_{b} \, \hat{M}^{(\Point,X),x}_{a}  \Big )_{\bob \alice''}  \,.			
